$('#rest').innerHTML=`<section class="gallery"><figure><img src="${photos[0]}" srcset="assets/fotografa-sorriso-480.jpg 480w, assets/fotografa-sorriso-960.jpg 960w, assets/fotografa-sorriso-1600.jpg 1066w" sizes="(max-width: 420px) 88vw, (max-width: 700px) 42vw, 29vw" decoding="async" width="1066" height="1600" alt="Mulher sorrindo, sentada em uma poltrona e segurando uma câmera" loading="lazy"><figcaption><span>01</span><div>Essência<small>RETRATOS FEMININOS</small></div></figcaption></figure><figure><img src="${photos[1]}" srcset="assets/retrato-natural-480.jpg 480w, assets/retrato-natural-960.jpg 740w" sizes="(max-width: 420px) 88vw, (max-width: 700px) 42vw, 29vw" decoding="async" width="740" height="1600" alt="Retrato em close de uma mulher sorrindo, com blusa marrom" loading="lazy"><figcaption><span>02</span><div>Presença<small>IMAGEM PROFISSIONAL</small></div></figcaption></figure><figure><img src="${photos[2]}" srcset="assets/fotografa-afeto-480.jpg 480w, assets/fotografa-afeto-960.jpg 960w, assets/fotografa-afeto-1600.jpg 1212w" sizes="(max-width: 420px) 88vw, (max-width: 700px) 42vw, 29vw" decoding="async" width="1212" height="1600" alt="Mulher com os olhos fechados, segurando uma câmera junto ao rosto" loading="lazy"><figcaption><span>03</span><div>Novos capítulos<small>MOMENTOS DE VIDA</small></div></figcaption></figure><figure class="gallery-wide"><img src="${photos[3]}" srcset="assets/retrato-movimento-480.jpg 480w, assets/retrato-movimento-960.jpg 960w, assets/retrato-movimento-1600.jpg 1600w" sizes="(max-width: 700px) 88vw, 86vw" decoding="async" alt="Mulher sorrindo com os cabelos em movimento, segurando um secador" loading="lazy" width="1600" height="1066"><figcaption><span>04</span><span class="wide-caption" data-new-caption>Leveza em movimento<small>PERSONALIDADE EM CADA RETRATO</small></span></figcaption></figure></section><section class="experience" id="experiencia"><div><span class="eyebrow">O ENSAIO COMEÇA NA CONVERSA</span><h2>Você não precisa<br>saber posar.<br><em>Só precisa chegar.</em></h2><p>Eu cuido da luz, dos detalhes e da direção.<br>Juntas, criamos espaço para a sua versão mais verdadeira aparecer.</p></div><div class="steps"><article><span>01</span><div><h3>Primeiro, eu escuto</h3><p>Conversamos sobre seu momento, suas referências e o que você quer comunicar.</p></div></article><article><span>02</span><div><h3>Um ensaio no seu ritmo</h3><p>Orientação de looks e direção leve, sem pressa e sem poses que não combinam com você.</p></div></article><article><span>03</span><div><h3>Imagens para levar com você</h3><p>Escolha dos retratos e entrega em galeria digital, com cuidado em cada detalhe.</p></div></article></div></section><section class="offer"><span class="eyebrow">ESCOLHA O SEU MOMENTO</span><h2>Qual história vamos contar?</h2><div class="packages"><article><span>PARA SE REDESCOBRIR</span><h3>Retrato pessoal</h3><p>Uma pausa para celebrar você, uma conquista ou um novo começo.</p><ul><li>Conversa de preparação</li><li>Direção durante todo o ensaio</li><li>Seleção de fotos em galeria digital</li></ul><a href="#contato" data-service="Retrato pessoal">Quero meu retrato</a></article><article><span>PARA OCUPAR SEU ESPAÇO</span><h3>Imagem profissional</h3><p>Sua personalidade e seu trabalho, traduzidos em imagens com intenção.</p><ul><li>Alinhamento com sua marca pessoal</li><li>Orientação de looks e cenário</li><li>Retratos para seus canais profissionais</li></ul><a href="#contato" data-service="Imagem profissional">Quero renovar minha imagem</a></article></div></section><section class="contact" id="contato"><div><span class="eyebrow">VAMOS CRIAR ALGO SEU?</span><h2>Sua próxima fase<br>merece um<br><em>novo retrato.</em></h2><p>Conte um pouco sobre o que você imagina.<br>O primeiro passo é uma boa conversa.</p><p class="demo-note">Demonstração de portfólio: use dados fictícios.<br>O pedido aparece no CRM desta sessão; nada é enviado.</p></div><form id="contactForm"><label>Como você se chama?<input name="name" autocomplete="name" required maxlength="80" placeholder="Seu nome"></label><label>E-mail para contato<input name="email" type="email" autocomplete="email" inputmode="email" required maxlength="120" placeholder="voce@exemplo.com"></label><label>Qual experiência você procura?<select name="service"><option>Retrato pessoal</option><option>Imagem profissional</option><option>Ainda quero descobrir</option></select></label><label>Quando você imagina fazer o ensaio?<select name="timing"><option>Nos próximos 30 dias</option><option>Nos próximos 3 meses</option><option>Estou pesquisando para o futuro</option></select></label><label>O que você gostaria de registrar?<textarea name="notes" rows="3" maxlength="1000" placeholder="Me conte sobre seu momento..."></textarea></label><button class="button">Simular pedido de orçamento</button><p id="formFeedback" role="status"></p></form></section><section class="faq"><h2>Antes do primeiro clique</h2><details><summary>Nunca fiz um ensaio. Isso é um problema?</summary><p>De jeito nenhum. A direção faz parte da experiência: você recebe orientações e tem tempo para se sentir à vontade.</p></details><details><summary>Como escolhemos o local e os looks?</summary><p>A proposta é pensada a partir da sua intenção. Na conversa de preparação, alinhamos referências, roupas e o ambiente do ensaio.</p></details><details><summary>Como funciona o orçamento?</summary><p>A proposta considera a experiência, o local e a quantidade de imagens. Nesta demonstração, o formulário cria um lead fictício para explorar esse processo no painel.</p></details></section><p class="credits">Fotografias do trabalho recente da fotógrafa.</p>`;
const stages=['Entrada','Follow-up','Negociação','Fechamento','Pós-venda','Nutrição'];const now=new Date();const iso=d=>new Date(d).toISOString().slice(0,10);const today=iso(now);const ago=n=>new Date(now.getTime()-n*86400000).toISOString();const future=n=>iso(now.getTime()+n*86400000);const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const days=d=>Math.max(0,Math.floor((Date.now()-new Date(d).getTime())/86400000));
let leads=[['Marina Costa','Imagem profissional',0,1,1600,0,'Conversar sobre sua marca pessoal'],['Bianca Rocha','Retrato pessoal',0,0,950,1,'Conhecer referências para o ensaio'],['Camila Souza','Retrato pessoal',1,5,950,-1,'Retomar a conversa sobre datas'],['Juliana Alves','Imagem profissional',1,3,1800,0,'Confirmar recebimento da proposta'],['Ana Beatriz','Imagem profissional',2,8,2200,1,'Alinhar local e quantidade de fotos'],['Luiza Martins','Retrato pessoal',3,12,1200,2,'Confirmar briefing do ensaio'],['Fernanda Lima','Imagem profissional',4,25,1800,5,'Pedir feedback sobre as fotos'],['Isabela Reis','Retrato pessoal',5,18,950,30,'Compartilhar referências e retomar interesse'],['Paula Melo','Imagem profissional',5,14,1600,21,'Retomar após reorganização do orçamento']].map((l,i)=>({id:String(i+1),name:l[0],service:l[1],stage:l[2],created:ago(l[3]),entered:ago(Math.min(l[3],i%4+1)),value:l[4],due:future(l[5]),action:l[6],email:'',reason:i===7?'Sem prazo de compra':i===8?'Orçamento indisponível':'',notes:'',history:[{at:ago(l[3]),text:'Lead demonstrativo criado'}]}));let query='',filter='all',view='pipeline',mobileStage=0;
$('#crm').innerHTML=`<div class="crm-shell"><aside><a class="brand" href="#">clara luz<span>RELACIONAMENTO</span></a><div class="side-label">SEU ESTÚDIO</div><button class="side active" data-view="pipeline">◫ &nbsp; Pipeline</button><button class="side" data-view="agenda">◷ &nbsp; Próximos contatos</button><button class="side" data-view="nutrition">♡ &nbsp; Nutrição</button><div class="sidebar-bottom">MODO DEMONSTRAÇÃO<small>Dados fictícios, mantidos apenas enquanto esta página está aberta.</small><button id="backSite">Ver landing page</button></div></aside><div class="crm-main"><div class="crm-heading"><div><span class="eyebrow">CADA CONVERSA IMPORTA</span><h1 id="crmTitle">Seu próximo capítulo.</h1><p>Acompanhe pessoas, oportunidades e o momento certo de retomar.</p></div><button class="button" id="newLead">+ Novo lead</button></div><div id="metrics" class="metrics"></div><div class="toolbar"><div class="tabs"><button data-filter="all" class="active">Todos</button><button data-filter="due">Retornos pendentes</button></div><input id="search" type="search" placeholder="Buscar por nome ou ensaio" aria-label="Buscar leads"></div><div id="workspace"></div><p class="crm-foot">Clique em um cartão para mudar a etapa, agendar retornos e registrar o motivo de nutrição. Nenhuma mensagem é enviada.</p></div></div>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}
function switchView(crm){$('#landing').hidden=crm;$('#crm').hidden=!crm;$('#switchView').textContent=crm?'Voltar para o site':'Conhecer o CRM';window.scrollTo(0,0);if(crm)render()}
$('#switchView').onclick=()=>switchView($('#crm').hidden);$('#backSite').onclick=()=>switchView(false);
function visible(){return leads.filter(l=>(l.name+' '+l.service).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||l.due&&l.due<=today))}
function render(){const pending=leads.filter(l=>l.due&&l.due<=today).length;$('#metrics').innerHTML=`<div><span>Leads no relacionamento</span><strong>${leads.length}</strong><small>Do primeiro contato à nutrição</small></div><div><span>Em negociação</span><strong>${money(leads.filter(l=>l.stage===2).reduce((a,l)=>a+l.value,0))}</strong><small>Valor estimado das propostas</small></div><div><span>Retornos para hoje ou atrasados</span><strong>${pending.toString().padStart(2,'0')}</strong><small>Conversas que pedem atenção</small></div><div><span>Vendas fechadas</span><strong>${money(leads.filter(l=>[3,4].includes(l.stage)).reduce((a,l)=>a+l.value,0))}</strong><small>Fechamento + pós-venda</small></div>`;const list=visible();$('#crmTitle').textContent=view==='pipeline'?'Seu próximo capítulo.':view==='agenda'?'Conversas para retomar.':'Cada pessoa tem seu tempo.';
if(view==='pipeline'){$('#workspace').innerHTML=`<label class="mobile-stage-label">Etapa do pipeline<select id="mobileStage">${stages.map((s,i)=>`<option value="${i}" ${i===mobileStage?'selected':''}>${esc(s)} (${list.filter(l=>l.stage===i).length})</option>`).join('')}</select></label><div class="board">${stages.map((s,i)=>`<section class="column ${i===mobileStage?'mobile-selected':''}"><div class="column-head"><h2><i class="dot dot-${i}"></i>${esc(s)}</h2><span>${list.filter(l=>l.stage===i).length}</span></div><p class="col-sum">${money(list.filter(l=>l.stage===i).reduce((a,l)=>a+l.value,0))}</p>${list.filter(l=>l.stage===i).map(card).join('')||'<p class="empty">Nenhum lead nesta etapa.</p>'}</section>`).join('')}</div>`}else{const items=list.filter(l=>view==='nutrition'?l.stage===5:!!l.due).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));$('#workspace').innerHTML=`${view==='nutrition'?'<div class="nurture-note"><strong>Um “agora não” ainda pode virar uma boa conversa.</strong><p>Guarde o motivo, combine uma data e ofereça algo relevante no próximo contato.</p></div>':''}<div class="agenda">${items.map(l=>`<button class="agenda-row" data-lead="${l.id}"><span class="avatar">${esc(l.name[0])}</span><span><strong>${esc(l.name)}</strong><small>${esc(l.service)} · ${esc(stages[l.stage])}</small></span><span>${esc(view==='nutrition'?l.reason||'Motivo não informado':l.action)}</span><span class="due ${l.due<today?'late':''}">${formatDate(l.due)}</span></button>`).join('')||'<p class="empty">Nenhum lead encontrado para este filtro.</p>'}</div>`}$$('[data-lead]').forEach(b=>b.onclick=()=>openLead(b.dataset.lead));if($('#mobileStage'))$('#mobileStage').onchange=e=>{mobileStage=Number(e.target.value);render()};document.dispatchEvent(new Event('crm:render'));}
function formatDate(d){if(!d)return'Sem retorno';return new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}
function card(l){return `<button class="lead-card" data-lead="${l.id}"><div class="card-top"><span class="avatar">${esc(l.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span>${days(l.created)}d no pipeline</span></div><h3>${esc(l.name)}</h3><p>${esc(l.service)}</p><strong>${money(l.value)}</strong><div class="card-divider"></div><span class="next-action">${esc(l.action||'Definir próximo passo')}</span><div class="card-bottom"><span class="due ${l.due&&l.due<today?'late':''}">${l.due&&l.due<today?'Atrasado · ':''}${formatDate(l.due)}</span><span>${days(l.entered)}d na etapa</span></div>${l.stage===5?`<span class="reason">${esc(l.reason||'Definir motivo')}</span>`:''}</button>`}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()});$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#search').oninput=e=>{query=e.target.value;render()};
function openLead(id){const existing=leads.find(l=>l.id===id),l=existing||{name:'',service:'Retrato pessoal',stage:0,value:950,due:today,action:'Primeiro contato',reason:'',email:'',notes:''};$('#leadDialog').innerHTML=`<form id="leadForm"><div class="dialog-heading"><div><span class="eyebrow">${existing?'RELACIONAMENTO':'NOVA OPORTUNIDADE'}</span><h2 id="leadDialogTitle">${existing?esc(l.name):'Um novo começo.'}</h2></div><button type="button" class="close" aria-label="Fechar">×</button></div><div class="form-grid"><label>Nome<input name="name" autocomplete="name" required maxlength="80" value="${esc(l.name)}"></label><label>E-mail<input name="email" type="email" autocomplete="email" inputmode="email" value="${esc(l.email)}"></label><label>Ensaio<select name="service">${['Retrato pessoal','Imagem profissional','Ainda quero descobrir'].map(x=>`<option ${x===l.service?'selected':''}>${x}</option>`).join('')}</select></label><label>Etapa<select name="stage">${stages.map((s,i)=>`<option value="${i}" ${i===l.stage?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Valor estimado (R$)<input name="value" type="number" min="0" max="1000000" step="1" required value="${l.value}"></label><label>Próximo retorno<input name="due" type="date" value="${l.due}"></label></div><label>Próxima ação<input name="action" maxlength="180" value="${esc(l.action)}" placeholder="Ex.: confirmar recebimento da proposta"></label><label id="reasonLabel">Motivo de nutrição<select name="reason"><option value="">Selecione um motivo</option>${['Sem prazo de compra','Orçamento indisponível','Aguardando uma ocasião','Comparando propostas','Sem resposta','Outro motivo'].map(s=>`<option ${s===l.reason?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Notas do relacionamento<textarea name="notes" maxlength="2000" rows="3">${esc(l.notes)}</textarea></label>${existing?`<div class="history"><h3>Histórico</h3><p>${days(l.created)} dias no pipeline · ${days(l.entered)} dias na etapa atual</p>${l.history.slice().reverse().map(h=>`<p><span>${new Date(h.at).toLocaleDateString('pt-BR')}</span> ${esc(h.text)}</p>`).join('')}</div>`:''}<div class="dialog-actions">${existing?'<button type="button" class="outline" id="contactDone">Registrar contato realizado</button>':''}<button class="button">Salvar lead</button></div></form>`;const form=$('#leadForm');const reason=()=>{$('#reasonLabel').hidden=form.stage.value!=='5';form.reason.required=form.stage.value==='5'};form.stage.onchange=reason;reason();$('.close').onclick=()=>$('#leadDialog').close();form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.name=data.name.trim();if(!data.name)return;data.stage=Number(data.stage);data.value=Number(data.value);if(existing){if(data.stage!==existing.stage){existing.history.push({at:new Date().toISOString(),text:`Movido de ${stages[existing.stage]} para ${stages[data.stage]}`});existing.entered=new Date().toISOString()}existing.history.push({at:new Date().toISOString(),text:'Informações e próximo passo atualizados'});Object.assign(existing,data)}else{leads.unshift({...data,id:crypto.randomUUID(),created:new Date().toISOString(),entered:new Date().toISOString(),history:[{at:new Date().toISOString(),text:'Lead criado manualmente'}]})}$('#leadDialog').close();render();toast('Lead salvo nesta demonstração.')};if(existing)$('#contactDone').onclick=()=>{existing.history.push({at:new Date().toISOString(),text:'Contato registrado manualmente como realizado'});existing.due='';render();openLead(existing.id);toast('Contato registrado. Agende o próximo retorno.')};$('#leadDialog').setAttribute('aria-labelledby','leadDialogTitle');if(!$('#leadDialog').open)$('#leadDialog').showModal()}
$('#newLead').onclick=()=>openLead();$$('[data-service]').forEach(a=>a.onclick=()=>$('#contactForm').service.value=a.dataset.service);
$('#contactForm').onsubmit=e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));if(!d.name.trim())return;leads.unshift({id:crypto.randomUUID(),name:d.name.trim(),email:d.email,service:d.service,stage:0,created:new Date().toISOString(),entered:new Date().toISOString(),value:0,due:today,action:'Responder ao pedido de orçamento',reason:'',notes:`Prazo: ${d.timing}. ${d.notes}`,history:[{at:new Date().toISOString(),text:'Entrada pelo formulário da landing page'}]});$('#formFeedback').innerHTML='Pedido simulado! Seu lead já está na etapa Entrada. <button type="button" id="seeLead">Ver no CRM</button>';$('#seeLead').onclick=()=>{view='pipeline';mobileStage=0;filter='all';query='';$('#search').value='';switchView(true)};f.reset();render()};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_demo_leads',title:'Consultar leads demonstrativos',description:'Lista os leads fictícios e suas etapas nesta sessão, sem enviar mensagens.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Use um objeto vazio.');return leads.map(({id,name,stage,due})=>({id,name,stage:stages[stage],nextContact:due}))}})).catch(()=>{})}catch{}}
